-- ---- Quiz items: 11 hand-written samples (ids 1-11, mixing real_news and
-- concept types) + 148 imported from Semiconductor_News (1).xlsx (ids 12-159,
-- all real_news; question/option/answer text comes from the spreadsheet) ----
-- NOTE: correct_option is deliberately spread across a/b/c (not clustered on
-- 'a') so a student can't pattern-guess the answer key. Keep this spread when
-- more content is added -- don't always put the correct choice first.
--
-- quiz.php should pull AT MOST 5 items per category at random, e.g.:
--   SELECT * FROM quiz_items WHERE category = ? ORDER BY RAND() LIMIT 5;
INSERT INTO quiz_items
    (id, category, question_type, news_article_id, question_text, option_a, option_b, option_c, correct_option, explanation, show_price_trend) VALUES
(1, 'geopolitical', 'real_news', 1,
 'The US tightened export rules on advanced AI chips to China. Which direction did NVDA move over the following days?',
 'Down sharply, well below the sector', 'Up, roughly in line with the broader sector', 'Flat, no reaction at all',
 'b',
 'NVDA rose about 3.1% while the SOXX sector benchmark rose about 1.0% over the same period — the stock moved with (and somewhat ahead of) the sector, not against it.',
 0),

(2, 'geopolitical', 'concept', NULL,
 'Which of these is the clearest example of a geopolitical news event for a semiconductor stock?',
 'A company beating its quarterly earnings estimate', 'A factory reporting a temporary equipment breakdown', 'A country announcing new export controls on chip technology',
 'c',
 'Export controls, tariffs, and diplomatic tension between chip-manufacturing nations are the defining feature of the geopolitical category.',
 0),

(3, 'earnings', 'real_news', 2,
 'TSMC beat quarterly revenue and margin estimates, citing strong AI chip demand. How did TSM perform against the sector benchmark the next day?',
 'It matched the sector exactly', 'It underperformed the sector, falling more than SOXX', 'It outperformed the sector by a wide margin',
 'b',
 'TSM fell about 2.05% while SOXX fell only about 0.55% — TSM underperformed its own sector despite beating estimates.',
 0),

(4, 'earnings', 'real_news', 6,
 'Micron raised its forward guidance on a memory-pricing recovery. How did MU move relative to the sector?',
 'It outperformed the sector benchmark', 'It underperformed the sector benchmark', 'It moved in the opposite direction of the sector',
 'a',
 'MU rose about 5.4% versus roughly 1.5% for SOXX — a clear outperformance, consistent with a company-specific guidance beat.',
 0),

(5, 'earnings', 'concept', NULL,
 'Why can a stock fall even after reporting record profit?',
 'Because earnings reports never affect stock prices', 'Because record profit always causes an automatic sell-off', 'Because the market reacts to results relative to expectations and guidance, not just absolute profit',
 'c',
 'Markets price in expectations ahead of the report. If guidance disappoints or margins miss forecasts, a stock can fall even on record headline profit.',
 0),

(6, 'macro', 'real_news', 3,
 'Global semiconductor sales rose for an eighth straight month. What is the most likely sector-wide effect?',
 'Only the single largest company reacts', 'Broad positive sentiment across most chip stocks, moving with the sector benchmark', 'No effect, since this is old news by the time it''s published',
 'b',
 'Industry-wide sales data is a macro signal that tends to lift sentiment across the whole sector at once, which is why it shows up in the SOXX benchmark rather than just one stock.',
 0),

(7, 'macro', 'concept', NULL,
 'If a stock and the SOXX sector benchmark move by almost the same percentage on the same day, what does that suggest about the news driving it?',
 'The news is more likely sector-wide (macro) than stock-specific', 'The news is definitely a corporate action', 'The news had no real effect on the market',
 'a',
 'When a stock tracks the benchmark closely, the driver is usually something affecting the whole industry rather than something unique to that one company.',
 0),

(8, 'corporate', 'real_news', 4,
 'Intel announced a new foundry partnership alongside a cost-cutting restructuring plan. How did INTC move compared to the sector?',
 'It moved identically to the sector', 'It significantly underperformed the sector benchmark', 'It significantly outperformed the sector benchmark',
 'c',
 'INTC rose about 6.7% versus roughly 0.9% for SOXX — a large stock-specific outperformance, typical of a company-level strategic announcement.',
 0),

(9, 'corporate', 'concept', NULL,
 'Which of these counts as a "corporate action" rather than a macro or earnings event?',
 'A company announcing a restructuring plan and new executive hires', 'An industry-wide report on global chip sales', 'A country imposing new tariffs on chip imports',
 'a',
 'Corporate actions are decisions a company makes about its own structure — restructuring, M&A, executive changes, buybacks — distinct from sector-wide macro data or a scheduled earnings report.',
 0),

(10, 'supply_chain', 'real_news', 5,
 'ASML flagged delayed shipments due to a shortage of a critical component from a sub-supplier. How did ASML move relative to the sector?',
 'It rose while the sector fell', 'It fell well beyond the sector benchmark''s decline', 'It fell by about the same amount as the sector',
 'b',
 'ASML fell about 5.3% while SOXX fell only about 1.4% — a much larger drop than the sector, consistent with a problem specific to ASML''s own supply chain.',
 0),

(11, 'supply_chain', 'concept', NULL,
 'Why might a shortage at one supplier affect multiple companies'' stock prices?',
 'Because supply chain issues only ever affect the supplier itself', 'Because supply chain news never affects stock prices', 'Because many chipmakers depend on the same specialized suppliers, so a delay can ripple forward to their customers',
 'c',
 'Chipmaking supply chains are highly interconnected — a shortage at one critical supplier can delay production for every company that depends on it.',
 0),

(12, 'geopolitical', 'real_news', 7,
 'Headline: ''Biden announces $8.5 billion Intel grant for chip plants''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises modestly (+0.52%): Subsidies lower fab financing costs, but gains were capped as aid was already widely anticipated alongside heavy matching CapEx.', 'Surges over +10%: The historic $8.5B grant completely eliminates Intel''s debt burden and guarantees immediate foundry profitability.', 'Drops over -5%: Investors sold off in panic fearing the grant''s strict restrictions would force Intel to abandon its dividend immediately.',
 'a',
 'The stock rose 0.52% the next day (trailing the sector''s +2.15%). The $8.5B CHIPS Act direct grant and up to $11B in loans validate federal backing and lower debt financing for Intel''s $100B fab expansion across AZ, OH, NM, and OR. However, upside was capped because the subsidy was already widely anticipated, while investors remained cautious about heavy matching CapEx, multi-year construction timelines, and foundry margin dilution.\nRelated Lesson: Lesson - Political: Lesson 2: Government Grants & Subsidies (Government checks offset $15B+ fab costs, but strings attached and high execution risks constrain immediate valuation gains).',
 1),

(13, 'geopolitical', 'real_news', 8,
 'Headline: ''US awards TSMC $6.6 bln subsidy for Arizona chip production''\nConsidering this is a Political/geo-political event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -3.5%: The expansion commitment to $65B was viewed as an unacceptable capital drain that would permanently crush TSMC''s gross margins.', 'Rises +1.83%: Federal subsidies lower overseas expansion costs and lock in advanced 2nm commitments from key US customers like Apple and Nvidia.', 'Surges +12%: The subsidy eliminates all geopolitical risk related to Taiwan, causing an immediate massive rerating of the stock.',
 'b',
 'The stock rose 1.83% the next day (outperforming the sector''s +1.08%). The U.S. awarded TSMC $6.6B in direct grants and up to $5B in loans, leading TSMC to expand its Arizona investment to $65B and add a third fab for 2nm chips by 2030. Federal co-funding lowers overseas expansion costs and locks in high-margin advanced node orders from US giants like Apple and Nvidia.\nRelated Lesson: Lesson - Political: Lesson 2: Government Grants & Subsidies & Lesson 3: Factory Location Risk (Alleviates fab construction costs while building backup capacity outside Taiwan to reduce the ''fear discount'').',
 1),

(14, 'geopolitical', 'real_news', 9,
 'Headline: ''U.S. to grant Samsung $6.4 billion for Texas chip manufacturing''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Gains +3.0%: The grant cements Samsung''s leadership over TSMC in US-based advanced logic chip fabrication.', 'Drops slightly (-0.2%): The news was completely ignored by investors because Samsung''s foundry business represents under 1% of total enterprise value.', 'Drops -2.68%: Anxiety over heavy matching CapEx during soft market conditions, reported Taylor fab delays to 2026, and lagging yields weighed on sentiment.',
 'c',
 'The stock dropped 2.68% the next day (underperforming the sector''s +0.76%). Despite receiving a $6.4B CHIPS Act grant to expand Texas investments to $40B+, investors grew concerned over the heavy capital commitment during soft memory/foundry conditions, reported commercial production delays at the Taylor fab to 2026, and lagging foundry yields compared to TSMC.\nRelated Lesson: Lesson - Political: Lesson 2: Government Grants & Subsidies (Strings Attached & Execution Delays: subsidies require massive matching CapEx and risk investor pushback if operational ramps lag).',
 1),

(15, 'geopolitical', 'real_news', 10,
 'Headline: ''Micron receives $6.1 billion CHIPS Act grant to build NY, Idaho fabs''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -4.61%: The subsidy was already priced in from prior leaks, triggering a ''sell-the-news'' reaction amid broad macro selloffs and massive long-term CapEx commitments.', 'Surges +7.5%: Massive government funding directly subsidizes memory chip prices, guaranteeing record gross margins for the next fiscal year.', 'Drops -15%: The grant terms banned Micron from selling DRAM and NAND products globally, triggering a catastrophic crash.',
 'a',
 'The stock dropped 4.61% the next day (tracking a -3.99% sector slump). The $6.14B preliminary CHIPS grant for mega-fabs in NY and Idaho was largely leaked and priced in beforehand. The drop was driven by macro rate pressures and investor anxiety over immense multi-year CapEx obligations required in the highly cyclical memory sector.\nRelated Lesson: Lesson - Political: Lesson 2: Government Grants & Subsidies (Priced-in expectations create sell-the-news reactions amid high capital intensity) & Lesson - Supply-chain: Lesson 3: Semiconductor Cycles.',
 0),

(16, 'geopolitical', 'real_news', 11,
 'Headline: ''China fails Micron''s products in security review, bars some purchases''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Crashed -12%: The CAC ban immediately wiped out half of Micron''s global revenue, triggering an emergency guidance downgrade.', 'Remains flat (0.00%): The regulatory action was already pre-warned and priced in, and Micron demonstrated capacity to redirect supply to other global customers.', 'Rallied +4.5%: Investors celebrated the ban as a catalyst for immediate retaliatory sanctions against Chinese domestic memory makers.',
 'b',
 'The stock was flat at 0.00% the next day (outperforming the sector''s -1.24% drop). China''s CAC barred critical infrastructure operators from buying Micron chips. While cutting off access to a key foreign market, the price held steady because Micron had already signaled this regulatory risk to markets and demonstrated the ability to redirect memory supply to other global customers.\nRelated Lesson: Lesson - Political: Lesson 1: Export Bans & Blacklists (The Ban Hammer & Sudden Shock: blacklists cutting off foreign customer bases, offset by customer diversification).',
 0),

(17, 'geopolitical', 'real_news', 12,
 'Headline: ''ASML cancels shipments of some machines to China after US request''\nConsidering this is a Political/geo-political event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -6.5%: Canceling high-end DUV shipments left ASML with stranded machinery inventory that could not be sold to other clients.', 'Surges +5.0%: Dutch government announced full financial compensation for all canceled shipments, eliminating any lost revenue.', 'Remains flat (0.00%): The market was pre-warned about export curbs, and ASML''s massive global backlog meant canceled tools were easily reallocated to other customers.',
 'c',
 'The stock remained flat at 0.00% the next day (beating the sector''s -2.15% decline). The Dutch government revoked export licenses for NXT:2050i/2100i DUV systems to China following US requests. ASML''s price held firm because the company had already pre-warned the market and its massive global lithography backlog allowed tool allocations to be easily absorbed elsewhere.\nRelated Lesson: Lesson - Political: Lesson 1: Export Bans & Blacklists (Canceled Orders & Revoked Licenses: government export interventions cushioned by deep monopoly order backlogs).',
 1),

(18, 'geopolitical', 'real_news', 13,
 'Headline: ''U.S. restricts exports of advanced Nvidia AI chips to Middle Eastern countries''\nConsidering this is a Political/geo-political event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Gains +0.20%: Nvidia clarified that Middle Eastern sales represent an immaterial portion of revenue, and overwhelming global AI chip demand absorbed any minor friction.', 'Plunged -8.0%: The Middle East restriction closed off Nvidia''s fastest-growing sovereign AI market, slashing forward data center projections.', 'Gains +6.5%: Middle Eastern governments responded by placing immediate multi-billion-dollar advance orders for consumer GeForce GPUs instead.',
 'a',
 'The stock gained 0.20% the next day (sector +0.69%). The US expanded export licensing for Nvidia A100/H100 chips to select Middle Eastern states to prevent tech diversion to China. The stock rose as Nvidia confirmed in an SEC filing that Middle East sales were an immaterial portion of total revenue and global enterprise AI demand far exceeded supply.\nRelated Lesson: Lesson - Political: Lesson 1: Export Bans & Blacklists (Geographic expansion of licensing curbs to prevent third-party tech diversion).',
 1),

(19, 'geopolitical', 'real_news', 14,
 'Headline: ''U.S. tightens export controls on AI chips to China, hitting Nvidia''\nConsidering this is a Political/geo-political event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rose +2.0%: Investors assumed Nvidia could immediately bypass the new rules without altering its product lineup or suffering sales interruptions.', 'Fell -3.96%: Performance density limits banned modified A800/H800 chips, sparking concerns over the immediate loss of 20-25% of China data center revenue and redesign costs.', 'Crashed -20%: The rules permanently prohibited Nvidia from manufacturing any advanced GPU chips worldwide, effectively halting operations.',
 'b',
 'The stock fell 3.96% the next day (underperforming the sector''s -1.80%). New Commerce Department rules introduced performance density limits, banning Nvidia''s modified A800/H800 chips and RTX 4090 from China. Investors panicked over the sudden forfeiture of 20-25% of data center sales and substantial redesign costs.\nRelated Lesson: Lesson - Political: Lesson 1: Export Bans & Blacklists (Sudden Shock & Extra Redesign Costs: closing loopholes on modified chips, instantly erasing key foreign sales).',
 1),

(20, 'geopolitical', 'real_news', 15,
 'Headline: ''TSMC opens first Japan chip plant in Kumamoto''\nConsidering this is a Political/geo-political event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -4.0%: Massive Japanese labor and construction overhead raised fears that JASM would remain unprofitable for the foreseeable future.', 'Surges +8.0%: Opening the Japan fab immediately doubled TSMC''s global wafer capacity within the first week of commercial launch.', 'Remains flat (0.00%): The opening was widely anticipated and on schedule, reinforcing execution credibility without sparking immediate post-event price volatility.',
 'c',
 'The stock was flat at 0.00% the next day (sector -0.10%; weekend event). TSMC opened its first Japan fab (JASM) on time and budget with $3.1B in Japanese subsidies. Investors viewed this as proof of TSMC''s superior overseas execution speed versus US delays, strengthening ties with anchor customers Sony and Toyota.\nRelated Lesson: Lesson - Political: Lesson 3: Factory Location Risk & Lesson 2: Government Grants & Subsidies (Mitigating Taiwan geopolitical concentration risk via subsidized overseas fabs).',
 0),

(21, 'geopolitical', 'real_news', 16,
 'Headline: ''Germany approves €5 billion subsidy for TSMC''s European microchip plant''\nConsidering this is a Political/geo-political event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Fell mildly (-0.54%): State aid and JV partners de-risk CapEx, but high European operating costs and long construction timelines kept investor enthusiasm muted during a sector dip.', 'Rallied +5.5%: €5B in subsidies provided pure non-dilutive profit that immediately increased TSMC''s quarterly dividend payout.', 'Plunged -7.0%: German automotive customers canceled existing foundry contracts in protest over government state aid.',
 'a',
 'The stock fell 0.54% the next day (outperforming the sector''s -1.83% drop). Germany approved a €5B subsidy for TSMC''s €10B Dresden joint venture (ESMC) with Bosch, Infineon, and NXP. While state aid and JV structure de-risk CapEx and guarantee auto orders, the stock dipped mildly on high European labor costs and long construction timelines.\nRelated Lesson: Lesson - Political: Lesson 2: Government Grants & Subsidies (Direct state checks reducing fab costs, balanced against European operational friction).',
 0),

(22, 'geopolitical', 'real_news', 17,
 'Headline: ''Germany and Intel agree on €10 billion subsidy for chip plant''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Surged +7.0%: Boosting the subsidy to €10B fully funded Intel''s European strategy without requiring any capital contributions from Intel itself.', 'Remains flat (0.00%): Increased government funding offered meaningful relief, but matching multi-billion-dollar CapEx commitments during ongoing PC market weakness checked stock gains.', 'Fell -8.5%: Investors fled the stock because EU regulations required Intel to license all proprietary x86 architecture to European rivals.',
 'b',
 'The stock was flat at 0.00% the next day (outperforming the sector''s -2.44% drop). Germany increased subsidies for Intel''s Magdeburg plant from €6.8B to €9.9B as Intel raised total investment to €30B+. The increased aid provided relief, but massive required matching corporate CapEx during market share losses kept gains in check.\nRelated Lesson: Lesson - Political: Lesson 2: Government Grants & Subsidies (Hard bargaining for government checks to offset soaring costs, balanced against corporate cash drain).',
 1),

(23, 'geopolitical', 'real_news', 18,
 'Headline: ''U.S. revokes Intel, Qualcomm licenses to sell to China''s Huawei''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
