 'c',
 'The stock edged up 0.30% the next day (outperforming the sector''s -0.37% decline). The US Commerce Department revoked licenses to supply laptop/phone chips to Huawei, leading Intel to trim Q2 guidance. The stock held steady because Huawei revenue exposure was already minimal and factored in after Huawei adopted domestic Kirin chips.\nRelated Lesson: Lesson - Political: Lesson 1: Export Bans & Blacklists (The Ban Hammer: sudden license revocations hitting foreign sales, though cushioned when previously anticipated).',
 1),

(24, 'geopolitical', 'real_news', 19,
 'Headline: ''France''s antitrust agency raids Nvidia offices in cloud probe''\nConsidering this is a Political/geo-political event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
