 'a',
 'The stock gained 0.95% the next day (outperforming the sector''s +0.36%). French regulators raided Nvidia''s offices in an antitrust probe targeting cloud and AI software dominance. The stock rose because dawn raids are early-stage procedural inquiries with no immediate operational penalty, and investors stayed focused on surging AI data center earnings.\nRelated Lesson: Lesson - Political: Lesson 1: Export Bans & Blacklists / Regulatory Intervention (Government scrutiny of dominant hardware/software ecosystems like CUDA).',
