(25, 'geopolitical', 'real_news', 20,
 'Headline: ''Intel scraps $5.4B Tower Semiconductor deal after China fails to approve''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
