 'b',
 'The stock fell 2.83% the next day (underperforming the sector''s -0.98% drop). Intel scrapped its $5.4B acquisition of Tower Semiconductor and paid a $353M termination fee after China''s SAMR failed to approve it before the deadline. The failure was a major strategic blow to Intel Foundry Services, depriving it of Tower''s mature-node customers and foundry expertise.\nRelated Lesson: Lesson - Political: Lesson 4: Tariffs & Trade Wars / Regulatory Blockades (China using antitrust delays as geopolitical payback against US semiconductor policies).',
 0),

(26, 'geopolitical', 'real_news', 21,
 'Headline: ''US grants indefinite waiver for Samsung, SK Hynix to supply China fabs''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
