 0),

(27, 'geopolitical', 'real_news', 22,
 'Headline: ''TSMC says it received US waiver to continue China operations''\nConsidering this is a Political/geo-political event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
