 1),

(28, 'geopolitical', 'real_news', 23,
 'Headline: ''US pressures Netherlands to stop ASML servicing China equipment''\nConsidering this is a Political/geo-political event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Crashed -6.0%: The servicing threat raised immediate fears that ASML''s high-margin recurring maintenance revenue would plummet across Asia.', 'Jumped +2.74%: Investors welcomed Dutch reluctance to enforce immediate unilateral bans, while booming global maintenance demand outside China provided strong revenue support.', 'Gained marginally (+0.1%): The news had no discernible impact because servicing and spare parts generate less than 2% of ASML''s annual corporate revenue.',
 'b',
 'The stock jumped 2.74% the next day (beating the sector''s +1.19%). Despite US pressure on the Netherlands to stop ASML servicing DUV tools in China, the stock rallied as the Dutch government resisted retroactive servicing bans, and investors recognized that ASML''s high-margin non-China servicing contracts and massive backlog insulated near-term cash flows.\nRelated Lesson: Lesson - Political: Lesson 1: Export Bans & Blacklists (Escalation from equipment sales bans to operational servicing bans, cushioned by strong monopoly pricing power).',
 1),

(29, 'geopolitical', 'real_news', 24,
 'Headline: ''Biden signs executive order restricting US investments in China tech''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
