 1),

(30, 'geopolitical', 'real_news', 25,
 'Headline: ''EU reaches agreement on €43 billion Chips Act''\nConsidering this is a Political/geo-political event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
