 'c',
 'The stock slipped 1.03% the next day (in line with the sector''s -1.09% decline). The EU finalized its €43B Chips Act to double Europe''s global chip share to 20% by 2030. TSMC fell with the market because the legislation had been fully anticipated, while investors weighed high European energy costs, strict subsidy conditions, and lengthy bureaucratic procedures.\nRelated Lesson: Lesson - Political: Lesson 2: Government Grants & Subsidies & Lesson 3: Factory Location Risk (Government expansion capital counterbalanced by bureaucratic red tape and operational friction).',
 0),

(31, 'geopolitical', 'real_news', 26,
 'Headline: ''ASML accuses former employee in China of misappropriating trade secrets''\nConsidering this is a Political/geo-political event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
