 'b',
 'The stock dropped 3.03% the next day (underperforming the sector''s -2.45% decline). ASML disclosed that a former employee in China misappropriated proprietary software data, potentially breaching export controls. The stock fell due to fears of intellectual property leakage to Chinese competitors and heightened risks of stricter US/Dutch export curbs.\nRelated Lesson: Lesson - Political: Lesson 1: Export Bans & Blacklists & Lesson 4: Tariffs & Trade Wars (Geopolitical tech warfare, IP theft risks, and regulatory fallout in sensitive jurisdictions).',
 0),

(32, 'geopolitical', 'real_news', 27,
