(33, 'geopolitical', 'real_news', 28,
 'Headline: ''China restricts exports of chipmaking metals gallium and germanium''\nConsidering this is a Political/geo-political event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
