(34, 'geopolitical', 'real_news', 29,
 'Headline: ''Samsung to invest $290M in Japan for advanced chip packaging facility''\nConsidering this is a Political/geo-political event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
