(35, 'geopolitical', 'real_news', 30,
 'Headline: ''Dutch government to restrict semiconductor tech exports, hitting ASML''\nConsidering this is a Political/geo-political event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
