(36, 'geopolitical', 'real_news', 31,
 'Headline: ''Raimondo tells Nvidia: U.S. will not let you bypass China chip curbs''\nConsidering this is a Political/geo-political event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
