(37, 'earnings', 'real_news', 32,
 'Headline: ''Nvidia Q1 earnings smash estimates, stock splits 10-for-1''\nConsidering this is a Earnings calls event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Surges +9.32%: Massive double beat driven by 427% Data Center growth and raised Q2 guidance to $28B easily outpaces already-high expectations.', 'Rises modestly (+1.2%): Strong earnings were almost entirely priced in by Wall Street, muting the post-earnings reaction.', 'Drops -4.5%: Investors sold off on fears that a 10-for-1 stock split would cause severe equity dilution and depress share value.',
 'a',
 'The stock surged 9.32% the following day (outperforming the sector''s -0.56% dip).\nExplanation & Article Drivers: Nvidia delivered a massive double beat with Q1 revenue jumping 262% YoY to $26.04B (above $24.65B expected) and adjusted EPS of $6.12 crushing expectations, driven by Data Center sales rocketing 427% YoY to $22.6B on insatiable Hopper GPU demand. Management also raised Q2 revenue guidance to $28.0B and announced a 10-for-1 stock split. The price surged because new revenue and margin expectations completely exceeded already-high Wall Street forecasts, while the split lowered retail barriers to entry.\nRelated DIP Lesson: Lesson - Earning call: Lesson 2 (Earnings Beats, Misses and Market Expectations) & Lesson 3 (Forward Guidance and Management Commentary): Illustrates how stock reaction equals ''New Information - Market Expectations'', where raising guidance above consensus forces analysts to increase future revenue and EPS forecasts.',
 1),

(38, 'earnings', 'real_news', 33,
 'Headline: ''Nvidia revenue up 265% on booming AI demand''\nConsidering this is a Earnings calls event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -3.0%: Investors worried that 265% revenue growth represented peak cyclical AI demand with inevitable deceleration ahead.', 'Soars +16.41%: A massive revenue beat ($22.1B vs $20.6B) and CEO commentary that GenAI hit a ''tipping point'' dispelled air-pocket spending fears.', 'Surges over +35%: Revenue more than tripled consensus expectations, causing the largest single-day market cap gain in global corporate history.',
 'b',
 'The stock soared 16.41% the following day (propelling a sector rally of +4.93%).\nExplanation & Article Drivers: Nvidia reported Q4 revenue of $22.10B (up 265% YoY) beating the $20.62B consensus, while gross margins expanded to a record 76.7%. Investors were concerned about a potential air pocket in cloud AI spending, but CEO Jensen Huang''s commentary that generative AI has reached a worldwide ''tipping point'' and Q1 guidance of $24.0B (beating expectations of $22.17B) eliminated spending cliff fears, driving massive valuation multiple expansion.\nRelated DIP Lesson: Lesson - Earning call: Lesson 3 (Forward Guidance and Management Commentary) & Lesson 5 (From Earnings Calls to Stock-Price Reactions): Demonstrates how executive demand commentary and margin guidance reset investor expectations about the durability of an earnings super-cycle.',
 1),

(39, 'earnings', 'real_news', 34,
 'Headline: ''Nvidia reports record Q2 revenue of $13.51 billion''\nConsidering this is a Earnings calls event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Soars +15.0%: Record Q2 revenue of $13.51B crushed consensus, triggering an immediate euphoric rally across the AI hardware complex.', 'Drops -6.5%: Investors aggressively took profits as gross margins contracted severely due to soaring TSMC packaging costs.', 'Finishes virtually flat (+0.08%): Despite record Q2 numbers and raised guidance, the stock had rallied 200%+ year-to-date, meaning blowout results were already fully priced in.',
 'c',
 'The stock finished virtually flat at +0.08% the following day (defying a sector decline of -3.30%).\nExplanation & Article Drivers: Nvidia doubled Q2 revenue to $13.51B and guided Q3 revenue to $16.0B (far above the $12.6B consensus) alongside a $25B share buyback. Despite historic results, the stock did not rally because shares had surged over 200% year-to-date into the report, meaning exceptional beats were already priced in. Investors also focused on supply commentary regarding TSMC CoWoS packaging bottlenecks, which capped near-term shipment upside.\nRelated DIP Lesson: Lesson - Earning call: Lesson 5 (Why Good Earnings Can Still Cause a Muted Reaction / Selloff) & Lesson 2 (Consensus vs Whisper Expectations): Shows that when exceptional results are already embedded in valuation, reported beats fail to generate further upside without supply expansion.',
 1),

(40, 'earnings', 'real_news', 35,
 'Headline: ''Nvidia issues blowout forecast as AI chips drive massive growth''\nConsidering this is a Earnings calls event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Skyrockets +24.36%: Blowout forward Q2 revenue guidance of $11B crushed consensus ($7.15B) by over 50%, completely resetting long-term AI revenue and valuation models.', 'Rallies +5.0%: Guidance was solid and slightly ahead of consensus, providing steady support in line with historical beat averages.', 'Plunges -8.0%: Wall Street panicked over massive supply chain bottlenecks and TSMC wafer shortages that could prevent Nvidia from meeting its targets.',
 'a',
 'The stock skyrocketed 24.36% the following day (sparking a +6.66% sector-wide surge).\nExplanation & Article Drivers: Nvidia reported solid Q1 results but shocked markets by guiding Q2 revenue to $11.0B (±2%), an unprecedented 53% above Wall Street consensus of $7.15B. Management explained that cloud hyperscalers were aggressively reallocating CapEx from traditional CPUs to GPUs for generative AI. This monumental guidance surprise proved that AI accelerator demand was exponential, triggering an immediate upward reset of future earnings multiples.\nRelated DIP Lesson: Lesson - Earning call: Lesson 3 (Forward Guidance and Management Commentary) & Lesson 5 (Earnings Calls as Expectation-Reset Events): Exemplifies the transmission mechanism where a massive guidance hike fundamentally resets analyst revenue and EPS models across the entire tech sector.',
 0),

(41, 'earnings', 'real_news', 36,
 'Headline: ''Intel issues weak Q2 guidance, shares tumble''\nConsidering this is a Earnings calls event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
