 0),

(42, 'earnings', 'real_news', 37,
 'Headline: ''Intel shares plunge as Q1 forecast falls far short of expectations''\nConsidering this is a Earnings calls event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rallies +6.0%: Management assured investors that seasonal Q1 PC weakness would be followed by record second-half server revenue.', 'Drops slightly (-1.5%): Sluggish Q1 guidance matched broader seasonal semiconductor trends without surprising analysts.', 'Plummets -11.91%: Q1 revenue guidance of $12.2B-$13.2B missed expectations ($14.2B) by over $1.5B, sparking fears that the PC recovery and foundry roadmap were stalling.',
 'c',
 'The stock plummeted 11.91% the following day (underperforming the sector''s -2.70% decline).\nExplanation & Article Drivers: While Intel met Q4 expectations, it guided Q1 revenue to $12.2B-$13.2B (far short of the $14.15B consensus) and guided adjusted EPS to just $0.01 (versus $0.22 expected). Management pointed to persistent inventory digestion in automotive (Mobileye) and programmable chips (Altera), along with traditional server softness, derailing investor hopes for a quick turnaround.\nRelated DIP Lesson: Lesson - Earning call: Lesson 2 (Earnings Beats, Misses and Market Expectations) & Lesson 3 (Customer Commentary & Inventory Digestion): Shows that forward guidance missing consensus by a wide margin triggers aggressive downward revisions that override historical quarterly results.',
 1),

(43, 'earnings', 'real_news', 38,
 'Headline: ''Intel beats Q3 earnings estimates, signals PC market recovery''\nConsidering this is a Earnings calls event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Surges +9.29%: Q3 results beat consensus and Q4 revenue guidance came in well ahead of forecasts, confirming that PC channel inventories had finally normalized.', 'Edged down (-0.5%): Beating low expectations was dismissed by analysts as an accounting anomaly driven by tax credits.', 'Surges +25.0%: Intel announced it had recaptured 100% of data center AI accelerator market share from Nvidia.',
 'a',
 'The stock surged 9.29% the following day (strongly outperforming the sector''s +1.08% rise).\nExplanation & Article Drivers: Intel posted Q3 adjusted EPS of $0.41 (beating $0.22 expected) and guided Q4 revenue above consensus. CEO Pat Gelsinger confirmed that customer PC inventory had normalized and client computing shipments were rebounding, driving gross margins up to 45.8%. The stock rallied because operating leverage returned as fixed manufacturing costs were spread over rising volume.\nRelated DIP Lesson: Lesson - Earning call: Lesson 1 (Understanding Earnings Reports: Gross Margin & Operating Leverage) & Lesson 5 (From Earnings Calls to Stock-Price Reactions): Demonstrates how customer inventory normalization enables factory utilization and gross margin recovery, fueling a relief rally.',
 1),

(44, 'earnings', 'real_news', 39,
 'Headline: ''Intel reports largest quarterly loss in company history''\nConsidering this is a Earnings calls event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Crashes -15.0%: Historic $2.8B quarterly net loss and a 36% revenue collapse triggered panic selling across institutional investors.', 'Rises +4.02%: Despite the record loss, results met low expectations, gross margins hit the bottom, and management signaled the worst of the inventory glut was over.', 'Remains unchanged (0.00%): Markets fully suspended trading on Intel shares pending clarity on federal CHIPS Act disbursement.',
