 'The stock rose 4.02% the following day (outperforming the sector''s +1.80% gain).\nExplanation & Article Drivers: Intel posted a record net loss of $2.8B in Q1 as revenue dropped 36% YoY due to massive PC inventory write-downs. Yet the stock rallied +4.02% because the catastrophic loss was already anticipated, and management''s commentary indicated that PC channel inventory was finally bottoming, with Q2 guidance pointing to sequential margin stabilization and $3B in cost cuts.\nRelated DIP Lesson: Lesson - Earning call: Lesson 5 (Why Weak Current Earnings Can Still Produce a Rally: The Market is Forward-Looking) & Lesson 2 (Expectations vs Absolute Performance): Illustrates that when worst-case results are fully priced in, forward signs of bottoming spark a price recovery.',
 1),

(45, 'earnings', 'real_news', 40,
 'Headline: ''TSMC beats Q1 profit estimates, flags strong AI chip demand''\nConsidering this is a Earnings calls event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
