(46, 'earnings', 'real_news', 41,
 'Headline: ''TSMC projects return to solid growth in 2024''\nConsidering this is a Earnings calls event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Gains +1.04%: Management projected a return to solid 20%+ revenue growth for 2024 driven by 3nm expansion and AI demand, providing strong forward guidance.', 'Drops -7.0%: Lower CapEx budget of $28B-$32B signaled management had lost confidence in long-term AI semiconductor growth.', 'Skyrockets +18.0%: TSMC announced it would triple foundry wafer prices for all major US customers including Apple and Nvidia.',
 'a',
 'The stock gained 1.04% the following day (sector +3.91%).\nExplanation & Article Drivers: TSMC reported Q4 profit beating estimates and guided full-year 2024 revenue growth of 20% to 25% in US dollars. CEO C.C. Wei noted that excess smartphone and PC customer inventories had cleared, while AI server accelerator demand was expanding at 50% annually, confirming that the foundry sector had transitioned from downturn to expansion.\nRelated DIP Lesson: Lesson - Earning call: Lesson 3 (Forward Guidance and Management Commentary) & Lesson 4 (Foundry Utilization & Advanced Nodes): Illustrates how positive multi-quarter revenue guidance and end-market inventory normalization provide visibility and drive stock gains.',
 0),

(47, 'earnings', 'real_news', 42,
 'Headline: ''TSMC posts first profit drop in four years, cuts 2023 outlook''\nConsidering this is a Earnings calls event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Plunges -8.0%: Reporting the first quarterly profit drop in four years confirmed that the global electronics supercycle was permanently broken.', 'Dips -0.62%: While profit dropped 23% and full-year revenue outlook was cut to a 10% decline, conservative expectations and AI demand cushioned the drop.', 'Surges +7.5%: Slashing 2023 guidance was cheered as a bold kitchen-sink strategy that guaranteed massive upside for 2024.',
 'b',
 'The stock dipped 0.62% the following day (trailing the sector''s +0.90% gain).\nExplanation & Article Drivers: TSMC reported a 23% profit decline in Q2 and cut its full-year revenue outlook from a slight contraction to a 10% decline. Management cited persistent consumer electronics weakness in China and announced that production at its Arizona fab would be delayed to 2025 due to specialist labor shortages, prompting cautious investor sentiment.\nRelated DIP Lesson: Lesson - Earning call: Lesson 3 (Forward Guidance & Risk Commentary) & Lesson 4 (Foundry Indicators: Utilization & Fab Delays): Explains how guidance downgrades reflecting prolonged customer inventory digestion and overseas fab execution friction constrain stock valuation.',
 1),

(48, 'earnings', 'real_news', 43,
 'Headline: ''TSMC warns of inventory glut, sees first-half revenue drop''\nConsidering this is a Earnings calls event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Gains +3.0%: High-margin 3nm Apple chip production ramp fully insulated TSMC from macro consumer electronics softness.', 'Drops slightly (-0.5%): Warning of inventory adjustments was already fully anticipated by Wall Street analysts.', 'Drops -4.39%: Warning that first-half revenue would drop 5% and inventory digestion would extend into mid-year dashed hopes of a swift V-shaped recovery.',
 'c',
 'The stock dropped 4.39% the following day (underperforming the sector''s -0.73% decline).\nExplanation & Article Drivers: TSMC warned of an enduring inventory glut across PC, smartphone, and general server markets, cutting full-year revenue guidance to a low-to-mid single-digit decline. Management warned that customer inventory corrections would persist through Q3, forcing lower capacity utilization across 7nm/6nm nodes and compressing gross margins.\nRelated DIP Lesson: Lesson - Earning call: Lesson 4 (Foundry Capacity Utilization & Fixed Cost Absorption) & Lesson 3 (Customer Inventory Commentary): Demonstrates how falling capacity utilization directly compresses gross margins because massive fixed fab costs are spread over fewer wafers.',
 1),

(49, 'earnings', 'real_news', 44,
 'Headline: ''Samsung Q1 operating profit jumps 933% on memory chip recovery''\nConsidering this is a Earnings calls event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +0.65%: Operating profit soaring 933% signaled the memory market''s turn to profitability, though broader macro headwinds and sector drops capped gains.', 'Surges +14.0%: A 933% profit jump caused Samsung shares to hit an all-time record high in a single trading session.', 'Crashes -6.0%: Investors penalized Samsung because profit expansion was driven entirely by non-semiconductor smartphone sales.',
 'a',
 'The stock rose 0.65% the following day (outperforming a -3.38% sector drop).\nExplanation & Article Drivers: Samsung''s Q1 operating profit surged 933% YoY to 6.61 trillion won, marking a dramatic return to profitability for its chip division. Profit was powered by surging DRAM (+20%) and NAND (+25%) average selling prices and strong enterprise SSD demand for AI servers, demonstrating that earlier industry production cuts had restored pricing power.\nRelated DIP Lesson: Lesson - Earning call: Lesson 4 (Memory Companies: DRAM/NAND ASP ↑ → Gross Margin ↑ → EPS ↑) & Lesson 2 (Earnings Beats): Connects memory price recovery to explosive operating profit rebounds following periods of severe cyclical undersupply.',
 1),

(50, 'earnings', 'real_news', 45,
 'Headline: ''Samsung flags weak Q1 earnings as memory chip demand remains sluggish''\nConsidering this is a Earnings calls event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Plummets -8.0%: Operating profit plunging 96% to 600B won marked the worst memory collapse in modern history.', 'Gains +1.24%: Despite a 96% profit drop, Samsung announced its first official memory production cut, catalyzing expectations of an earlier market bottom.', 'Rallies +12.0%: Production cuts allowed Samsung to immediately double DRAM contract prices the following week.',
 'b',
 'The stock gained 1.24% the following day (beating the sector''s +0.50% rise).\nExplanation & Article Drivers: Samsung reported a 34% drop in Q4 operating profit and cautioned that Q1 earnings would remain weak as consumer memory demand recovered slowly. However, shares gained because management confirmed it would maintain production discipline on legacy memory while accelerating HBM3E production for AI customers, signaling that supply growth remained restrained.\nRelated DIP Lesson: Lesson - Earning call: Lesson 5 (Why Weak Current Earnings Can Produce a Rally: Future Expectations vs Trailing Results) & Lesson 3 (Supply Commentary & Output Discipline): Illustrates how investor expectations focus on future supply-demand balance rather than depressed current earnings.',
 0),

(51, 'earnings', 'real_news', 46,
 'Headline: ''Samsung expects chip demand to recover slowly after 95% profit plunge''\nConsidering this is a Earnings calls event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rallies +5.0%: Reassurances that memory demand would bottom in the second half drove aggressive dip-buying.', 'Plunges -12.0%: Management warned that memory price declines would accelerate through 2025, triggering widespread capitulation.', 'Falls -1.53%: A staggering 95% profit drop combined with cautionary commentary that demand recovery would be slow and uneven dampened investor enthusiasm.',
 'c',
 'The stock fell 1.53% the following day (underperforming the sector''s +2.19% gain).\nExplanation & Article Drivers: Samsung reported a 95% drop in Q2 operating profit as its semiconductor unit suffered a 4.36 trillion won ($3.4B) operating loss. The stock declined because management warned of a slow, protracted second-half recovery, extended production cuts on NAND flash, and revealed that Samsung was lagging SK Hynix in qualifying and shipping HBM to Nvidia.\nRelated DIP Lesson: Lesson - Earning call: Lesson 3 (Management Demand Commentary) & Lesson 4 (Memory Indicators: HBM Adoption & Market Share): Highlights how falling behind in high-margin advanced memory (HBM) dampens investor confidence during an industry cyclical inflection.',
 0),

(52, 'earnings', 'real_news', 47,
 'Headline: ''Samsung posts worst profit in 14 years, says memory output cuts to continue''\nConsidering this is a Earnings calls event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Gains +1.39%: A massive 4.58T won semiconductor division loss met pessimistic expectations, while extended production cuts reinforced confidence in future pricing recovery.', 'Drops -6.5%: Heavy device solutions losses forced Samsung to suspend capital spending on advanced EUV memory nodes.', 'Surges +9.0%: Samsung announced it would completely divest its memory division to focus exclusively on contract foundry.',
 'a',
 'The stock gained 1.39% the following day (sector +1.80%).\nExplanation & Article Drivers: Samsung posted its lowest operating profit in 14 years, with a 4.58 trillion won chip loss. Yet the stock rallied because Samsung made the historic announcement that it was meaningfully cutting memory production, abandoning its historic stance of never cutting output. The market celebrated this supply capitulation as the definitive trigger for memory price recovery.\nRelated DIP Lesson: Lesson - Earning call: Lesson 5 (Why Weak Current Earnings Can Produce a Rally) & Lesson 4 (Memory Supply Discipline: Bit Production Cuts → Inventory Normalization → Future ASP Rise): Shows how supplier output cuts reverse oversupply and catalyze cyclical rebounds.',
 1),

(53, 'earnings', 'real_news', 48,
 'Headline: ''Micron delivers surprise Q2 profit, driven by AI memory demand''\nConsidering this is a Earnings calls event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises modestly (+1.5%): Surprise quarterly profitability was offset by concerns over high CapEx spending for fiscal 2024.', 'Surges +14.13%: Delivering a surprise profit of $0.42/share (vs. expected $0.25 loss) and robust AI HBM revenue guidance sparked a dramatic memory rerating.', 'Drops -4.0%: Investors sold off in disappointment that Micron''s HBM3E chips were already sold out through calendar 2024.',
 'b',
 'The stock surged 14.13% the following day (outperforming the sector''s +2.15% gain).\nExplanation & Article Drivers: Micron shocked Wall Street by posting unexpected Q2 adjusted EPS of $0.42 (beating the -$0.25 consensus loss) on revenue of $5.82B (crushing $5.35B expected). CEO Sanjay Mehrotra issued blowout Q3 guidance and announced that Micron''s HBM3E supply for Nvidia H200 AI GPUs was completely sold out through 2025 at fixed pricing, driving massive gross margin expansion.\nRelated DIP Lesson: Lesson - Earning call: Lesson 2 (Surprise Earnings Beats) & Lesson 4 (Memory Indicators: HBM Demand & Pricing Power): Demonstrates how a dramatic swing from losses to profit combined with sold-out advanced memory capacity creates a powerful re-rating of future earnings.',
 1),

(54, 'earnings', 'real_news', 49,
 'Headline: ''Micron issues upbeat Q2 revenue forecast on stabilizing memory prices''\nConsidering this is a Earnings calls event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -3.5%: Revenue guidance above expectations was overshadowed by cautious PC and smartphone customer inventory commentary.', 'Surges +22.0%: Upbeat revenue guidance prompted analysts to forecast record gross margins for the next five years.', 'Jumps +8.63%: Upbeat Q2 revenue guidance ($5.3B vs $5.03B consensus) provided concrete proof that DRAM and NAND pricing had inflected positively.',
 'c',
 'The stock jumped 8.63% the following day (outperforming the sector''s +2.77% gain).\nExplanation & Article Drivers: Micron posted narrower Q1 losses and guided Q2 revenue of $5.1B-$5.5B (above $4.97B consensus). Management confirmed that customer excess inventories had normalized across PCs and mobile, while commercial DRAM and NAND contract prices were rebounding, signaling that the severe 2022-2023 memory downturn was officially over.\nRelated DIP Lesson: Lesson - Earning call: Lesson 3 (Forward Guidance and Management Commentary) & Lesson 5 (Connecting Inventory Normalization to Future Revenue Expectations): Explains how guidance exceeding consensus due to price increases triggers analyst forecast upgrades.',
 1),

(55, 'earnings', 'real_news', 50,
 'Headline: ''Micron issues wider-than-expected Q1 loss forecast''\nConsidering this is a Earnings calls event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -4.41%: Forecasting a wider-than-expected Q1 loss of $1.00-$1.14 per share signaled that memory margin recovery would take longer than investors hoped.', 'Rallies +6.0%: Investors ignored the guidance and focused exclusively on Micron''s upcoming HBM shipments for Nvidia GPUs.', 'Crashes -16.0%: Wider loss guidance raised immediate liquidity concerns and forced an emergency bond issuance.',
 'a',
 'The stock fell 4.41% the following day (underperforming the sector''s +1.85% gain).\nExplanation & Article Drivers: While Micron beat Q4 revenue estimates, it guided to a wider-than-expected fiscal Q1 loss of $1.00 to $1.14 per share (versus -$0.88 expected) and projected negative gross margins (-4%). Investors sold off the stock because memory recovery outside of AI servers was taking longer than expected, and higher per-unit manufacturing costs weighed on near-term margins.\nRelated DIP Lesson: Lesson - Earning call: Lesson 3 (Forward Guidance: Negative Margins & Widening Losses) & Lesson 2 (Expectations vs Absolute Performance): Demonstrates that a quarterly revenue beat is quickly overshadowed when forward margin guidance disappoints consensus.',
 0),

(56, 'earnings', 'real_news', 51,
 'Headline: ''Micron posts worst quarterly loss on record, writes down inventory''\nConsidering this is a Earnings calls event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Plummets -10.0%: Reporting a record $2.3B quarterly loss and taking a $1.4B inventory writedown frightened institutional investors.', 'Rallies +7.19%: CEO Sanjay Mehrotra declared customer inventories had peaked and memory supply-demand would rebalance, signaling the cyclical trough.', 'Remains flat (0.00%): Markets showed zero reaction to the loss because Micron had pre-released the exact figures two weeks earlier.',
 'b',
 'The stock rallied 7.19% the following day (outperforming the sector''s +3.21% gain).\nExplanation & Article Drivers: Micron reported a record net loss of $2.3B in fiscal Q2 and took a massive $1.4B inventory write-down as memory prices plunged over 20%. Despite these abysmal numbers, the stock surged +7.19% because management announced severe CapEx cuts (>40% YoY), a 15% headcount reduction, and major wafer start curtailments, convincing investors the market had hit maximum pain and was bottoming.\nRelated DIP Lesson: Lesson - Earning call: Lesson 5 (Why Weak Current Earnings Can Still Produce a Rally) & Lesson 4 (Memory Inventory Write-Downs & CapEx Cuts): Shows how aggressive capacity reduction and ''kitchen-sink'' inventory write-downs clear the deck for cyclical price recovery.',
 0),

(57, 'earnings', 'real_news', 52,
 'Headline: ''ASML misses Q1 order estimates, shares drop''\nConsidering this is a Earnings calls event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rallies +4.5%: Resilient gross margins and strong long-term semiconductor CapEx projections overshadowed quarterly order volatility.', 'Plunges -11.0%: Q1 bookings missing consensus sparked panic that chipmakers were canceling advanced EUV factory expansions.', 'Falls -2.05%: Q1 net bookings of €3.6B missed consensus (€5.4B) sharply, reigniting doubts over the pace of customer fab construction.',
 'c',
 'The stock fell 2.05% the following day (in line with the sector''s -1.77% decline).\nExplanation & Article Drivers: ASML reported Q1 net bookings of €3.6B ($3.8B), falling short of the €5.4B consensus estimate, with high-end EUV bookings dropping to €656M. While ASML maintained full-year guidance calling 2024 a ''transition year'' ahead of strong 2025 growth, the order shortfall raised market anxiety regarding the timing of customer fab expansions and equipment purchase decisions.\nRelated DIP Lesson: Lesson - Earning call: Lesson 4 (Semiconductor Equipment: Bookings & Backlog as Leading Indicators) & Lesson 2 (Beats vs Misses): Explains why equipment stocks react sharply to net bookings, which serve as the primary barometer for future foundry and memory CapEx.',
 1),

(58, 'earnings', 'real_news', 53,
 'Headline: ''ASML reports record Q4 orders, boosted by advanced chip demand''\nConsidering this is a Earnings calls event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Gains +2.57%: Record Q4 bookings of €9.19B (more than triple Q3 levels) driven by cutting-edge EUV lithography demand confirmed an inflection in chipmaker CapEx.', 'Drops -4.0%: Analysts feared that massive Q4 bookings pulled forward demand from 2025 and would create an order vacuum.', 'Surges +15.0%: Record bookings prompted ASML to double its dividend and announce immediate delivery of Next-Gen High-NA systems.',
 'a',
 'The stock gained 2.57% the following day (outperforming the sector''s -0.28% dip).\nExplanation & Article Drivers: ASML reported that Q4 net bookings tripled sequentially to a record €9.19B, blowing past the €3.6B consensus, with EUV orders accounting for €5.6B. The massive order intake showed that foundries and memory makers were actively securing tools for 2nm/3nm ramps and AI chips, giving investors clear revenue visibility for 2025 and boosting equipment sentiment.\nRelated DIP Lesson: Lesson - Earning call: Lesson 4 (Equipment Indicators: Order Intake & Backlog Growth) & Lesson 5 (Stock-Price Reactions): Demonstrates how a dramatic expansion in equipment backlog provides revenue certainty and drives valuation multiple expansion.',
 1),

(59, 'earnings', 'real_news', 54,
 'Headline: ''ASML warns 2024 sales will be flat as semiconductor industry struggles''\nConsidering this is a Earnings calls event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Plunges -9.0%: Warning that 2024 net sales would be flat compared to 2023 caused investors to abandon semiconductor equipment stocks.', 'Rises +0.77%: Characterizing 2024 as a transitional ''bridge year'' to prepare for significant 2025 growth reassured markets that secular demand was intact.', 'Surges +8.5%: Guidance for flat 2024 revenue beat whispers that ASML''s shipments would contract by 25% due to export restrictions.',
 'b',
 'The stock rose 0.77% the following day (outperforming the sector''s -1.54% drop).\nExplanation & Article Drivers: ASML posted solid Q3 profits but issued cautious guidance that 2024 revenue would be flat compared to 2023 due to customer pushouts. The stock held up because the pause was already expected by investors, and management affirmed that 2025 would see massive growth as subsidized fab buildouts in the US, Europe, and Asia reached tool installation phases.\nRelated DIP Lesson: Lesson - Earning call: Lesson 3 (Forward Guidance & Transition-Year Commentary) & Lesson 5 (Earnings Calls as Expectation-Reset Events): Illustrates how well-telegraphed flat guidance avoids selloffs when paired with strong multi-year secular tailwinds.',
 1),

(60, 'earnings', 'real_news', 55,
 'Headline: ''ASML raises 2023 outlook on strong Chinese demand for older machines''\nConsidering this is a Earnings calls event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Surges +7.0%: Raising full-year sales growth guidance from 25% to 30% on Chinese DUV demand triggered widespread analyst upgrades.', 'Remains flat (0.00%): Increased guidance was completely neutral because gross margin targets remained unchanged.', 'Tumbles -5.54%: Despite raising 2023 revenue guidance, management warned customers were delaying fab schedules, while China revenue reliance raised geopolitical vulnerability.',
 'c',
 'The stock tumbled 5.54% the following day (underperforming the sector''s -3.64% drop).\nExplanation & Article Drivers: ASML raised its 2023 revenue growth outlook to 30% on surging shipments of DUV tools to Chinese customers rushing to install tools ahead of export restrictions. However, the stock slumped because investors viewed Chinese demand as temporary pull-forward that would create a revenue cliff in 2024, while non-China fab projects (TSMC Arizona) faced construction pushouts.\nRelated DIP Lesson: Lesson - Earning call: Lesson 5 (Why Good Earnings Can Still Cause a Selloff: Pull-Forward Demand) & Lesson 4 (Geographic Revenue Exposure & Export Restrictions): Shows that raised guidance can trigger selling if revenue growth is driven by unsustainable regulatory pull-forward.',
 0),

(61, 'earnings', 'real_news', 56,
 'Headline: ''Nvidia Q3 earnings beat, but gaming revenue drops 51%''\nConsidering this is a Earnings calls event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Slipped -1.45%: Although total revenue beat estimates, a staggering 51% YoY collapse in Gaming revenue reminded investors of post-crypto inventory overhangs.', 'Surged +12.0%: Blowout Data Center growth completely overshadowed consumer gaming weakness, driving an immediate new all-time high.', 'Crashed -10.0%: The halving of gaming sales led Wall Street to downgrade Nvidia from Buy to Sell across major brokerages.',
 'a',
 'The stock slipped 1.45% the following day (trailing the sector''s +0.79% rise).\nExplanation & Article Drivers: Nvidia beat Q3 consensus with $5.93B in revenue and EPS of $0.58. However, gaming revenue plunged 51% YoY to $1.57B as consumer channel inventory collapsed following the post-pandemic and crypto-mining unwinds. Even though Data Center revenue grew 31% YoY to $3.83B, it was not yet sufficient to fully offset the gaming collapse, prompting mild profit-taking.\nRelated DIP Lesson: Lesson - Earning call: Lesson 4 (Fabless Indicators: Segment Revenue Divergence) & Lesson 1 (Understanding Earnings: End-Market Revenue Breakdown): Illustrates how inventory corrections in a major legacy segment (gaming) can temporarily overshadow growth in emerging segments.',
 0),

(62, 'earnings', 'real_news', 57,
 'Headline: ''Nvidia posts 69% sales growth but flags bigger China export-control hit''\nConsidering this is a Earnings calls event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Plunged -6.5%: Warning of a steep drop in Q4 China sales due to newly expanded US export controls triggered heavy institutional selling.', 'Rose +3.25%: Massive 206% YoY Data Center revenue growth easily outweighed the expected China decline, reassuring markets of insatiable Western cloud demand.', 'Surged +18.0%: Nvidia reported that new China export controls had zero effect on any current or future GPU products.',
 'b',
 'The stock rose 3.25% the following day (outperforming the sector''s +0.41% gain).\nExplanation & Article Drivers: Nvidia reported fiscal Q1 sales jumping 69% YoY, but disclosed that U.S. export controls on H20 chips cost ~$2.5B in the quarter and guided to an ~$8B revenue hit in Q2. The stock rallied because surging demand from Western cloud hyperscalers and sovereign AI programs far exceeded supply, proving that global AI momentum easily absorbed the Chinese market restrictions.\nRelated DIP Lesson: Lesson - Earning call: Lesson 3 (Quantifying Export Control Risk Commentary) & Lesson 2 (Expectations vs Absolute Performance): Demonstrates how insatiable global core product demand neutralizes localized geopolitical and regulatory headwinds.',
 1),

(63, 'earnings', 'real_news', 58,
 'Headline: ''TSMC heads into Q4 earnings with record profit expected on AI demand''\nConsidering this is a Earnings calls event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
