 1),

(64, 'earnings', 'real_news', 59,
 'Headline: ''ASML Q1 bookings miss estimates as tariffs cloud 2025-2026 outlook''\nConsidering this is a Earnings calls event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rose +0.82%: While Q1 bookings missed expectations and geopolitical tariff concerns lingered, resilient gross margins and reaffirmed 2025 targets supported the stock.', 'Crashed -8.0%: Impending tariff risks prompted major customers like Intel and TSMC to cancel existing lithography machinery orders.', 'Surges +7.5%: ASML announced full exemption from all US and European international trade tariffs.',
 'a',
 'The stock rose 0.82% the following day (outperforming the sector''s -0.50% dip).\nExplanation & Article Drivers: ASML reported Q1 net bookings of €3.9B, missing consensus expectations as tariff and trade war concerns created customer hesitation. However, the stock held positive ground because ASML reaffirmed its full-year guidance and management clarified that AI demand for advanced logic and HBM memory lithography was resilient, meaning tool orders were merely delayed rather than canceled.\nRelated DIP Lesson: Lesson - Earning call: Lesson 4 (Equipment Indicators: Bookings vs Long-Term Backlog) & Lesson 3 (Risk Commentary): Demonstrates that an order booking miss does not damage stock valuation if management confirms underlying structural demand and preserves annual guidance.',
 1),

(65, 'earnings', 'real_news', 60,
 'Headline: ''Intel posts deeper Q2 loss and forecasts steeper Q3 loss despite stronger sales outlook''\nConsidering this is a Earnings calls event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rose +3.0%: Stronger sales outlook for the second half of the year convinced investors that turnaround efforts were taking hold.', 'Plunged -8.53%: Widening Q2 net losses ($1.6B) and worse-than-feared Q3 loss guidance of -$0.24/share revealed deepening foundry cash burn and margin erosion.', 'Crashed -25.0%: Intel announced the immediate abandonment of all internal manufacturing to become a pure fabless chip designer.',
 'b',
 'The stock plunged 8.53% the following day (sharply underperforming the flat sector at -0.01%).\nExplanation & Article Drivers: While Intel''s Q2 revenue of $12.9B modestly beat consensus, its adjusted loss was much worse than expected, and management forecast an even steeper Q3 loss due to restructuring charges and manufacturing yield hurdles. Investors aggressively punished the stock as gross margin contraction and rising foundry losses overshadowed revenue stabilization.\nRelated DIP Lesson: Lesson - Earning call: Lesson 2 (Revenue Beat vs EPS Miss) & Lesson 3 (Margin Guidance ↓ → Profitability Collapse): Demonstrates that top-line revenue beats are completely disregarded by the market when gross margins and bottom-line earnings collapse.',
 0),

(66, 'earnings', 'real_news', 61,
 'Headline: ''Micron raises Q4 revenue, EPS and margin forecasts as AI memory demand strengthens''\nConsidering this is a Earnings calls event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Crashed -5.0%: Raising forecasts in the middle of a quarter was viewed as an act of desperation to artificially support the stock.', 'Surges +14.0%: Raised guidance indicated Micron''s gross margins would reach an unprecedented 60% within the next quarter.', 'Rose +3.26%: Upward revisions to Q4 revenue, EPS, and gross margin guidance confirmed accelerating pricing power for high-bandwidth memory (HBM) chips.',
 'c',
 'The stock rose 3.26% the following day (matching the sector''s +3.20% gain).\nExplanation & Article Drivers: In an intra-quarter guidance update, Micron raised its Q4 revenue forecast to $11.2B, adjusted EPS to $2.85, and gross margins to 44.5%. The guidance hike was propelled by accelerating HBM memory shipments to AI server customers and tight industry DRAM supply, creating strong operating leverage and lifting Wall Street consensus estimates.\nRelated DIP Lesson: Lesson - Earning call: Lesson 3 (Forward Guidance: Intra-Quarter Guidance Upgrades) & Lesson 4 (Memory Indicators: DRAM/HBM ASP ↑ + Margin ↑ → Future EPS ↑): Explains the direct transmission mechanism where upward guidance revisions directly boost stock valuation.',
 0),

(67, 'macro', 'real_news', 62,
 'Headline: ''Federal Reserve raises rates by 25 basis points, acknowledges inflation is easing''\nConsidering this is a Industry-wide (macro) event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +3.68%: Powell''s mention of a ''disinflationary process'' signaled the end of aggressive rate hikes, lowering bond yields and boosting high-growth tech valuations.', 'Plunges -6.0%: Raising benchmark interest rates by 25 bps increased corporate borrowing costs, triggering panic selling in capital-intensive tech.', 'Surges +15.0%: The Fed announced an emergency rate cut to 0%, triggering the largest single-day Nasdaq rally of the decade.',
 'a',
 'The stock price rose 3.68% the following day (outperforming the sector''s +2.32% gain).\nExplanation & Article Drivers: The Federal Reserve raised interest rates by 25 bps as expected, but Chair Jerome Powell acknowledged for the first time that the ''disinflationary process has started.'' Investors cheered the commentary as a clear signal that the aggressive rate-hike campaign was near its conclusion. Falling Treasury yields relieved valuation multiple compression on high-growth equities, sparking aggressive buying in premier AI leaders like Nvidia.\nRelated DIP Lesson: Lesson - Industry macro: Lesson 1 (The Cost of Capital: Interest Rate Hikes & Cuts) & Lesson 2 (Inflation Indicators as Market Catalysts): Demonstrates how falling benchmark bond yields reduce the equity discount rate, driving immediate Price-to-Earnings (P/E) multiple expansion for high-growth tech stocks.',
 1),

(68, 'macro', 'real_news', 63,
