 'The stock gained 0.42% the following day (outperforming the flat sector at +0.05%).\nExplanation & Article Drivers: ASML and Samsung signed a joint agreement to invest 1 trillion won (~$760M) to build an advanced research facility in South Korea focused on next-generation High-NA EUV lithography. The partnership bolstered ASML''s stock by securing joint funding for R&D and ensuring immediate commercial adoption of its most advanced lithography equipment by a premier memory client.\nRelated DIP Lesson: Lesson - Corporate actions: Lesson 5 (Joint Ventures and Strategic Alliances) & Lesson - Supply-chain: Lesson 1 (Equipment Ecosystem Collaboration): Joint R&D alliances between toolmakers and chip manufacturers share development risks and secure future commercial tool adoption.',
 0),

(112, 'corporate', 'real_news', 107,
 'Headline: ''Intel to sell $1.5 billion stake in Mobileye''\nConsidering this is a Corporate actions event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -4.5%: Liquidating a $1.5B stake in Mobileye signaled that autonomous driving technology was losing strategic priority at Intel.', 'Remains flat (0.00%): The transaction was completely ignored by markets as an internal asset reshuffle with no liquidity impact.', 'Surges +3.68%: Selling 35 million Mobileye shares raised $1.5B in non-dilutive cash, strengthening Intel''s balance sheet without giving up corporate control.',
 'c',
 'The stock surged 3.68% the following day (outperforming the sector''s +1.20% rise).\nExplanation & Article Drivers: Intel sold 38.5 million shares of its Mobileye subsidiary in a secondary offering, generating approximately $1.5 billion in cash while retaining an 88% controlling stake. The stock rallied because the sale generated non-dilutive liquidity to finance Intel''s massive fab construction without sacrificing governance control over Mobileye''s autonomous driving business.\nRelated DIP Lesson: Lesson - Corporate actions: Lesson 1 (Strategic Restructuring and Spinoffs: Partial Spinoffs & Stake Sales): Monetizing minority equity stakes in subsidiary assets provides vital non-debt liquidity to fund parent company CapEx without diluting parent shareholders.',
 1),

(113, 'corporate', 'real_news', 108,
 'Headline: ''TSMC board approves $3.5 billion capital injection for Arizona subsidiary''\nConsidering this is a Corporate actions event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Slides -5.31%: A $3.5B capital injection into TSMC Arizona reminded investors of soaring construction costs, labor friction, and margin-dilutive overseas expansion.', 'Surges +6.0%: Expanding US capital allocation signaled that the Arizona facility would reach commercial production ahead of schedule.', 'Gains +1.0%: Capital transfers to wholly-owned subsidiaries are standard internal corporate finance moves with zero stock price effect.',
 'a',
 'The stock slid 5.31% the following day (underperforming the sector''s +0.40% gain).\nExplanation & Article Drivers: TSMC''s board approved a $3.5 billion capital injection for its Arizona subsidiary to cover soaring construction expenses and labor premiums in Phoenix. The stock suffered a steep selloff as the additional funding confirmed that overseas fab replication was proving significantly more expensive than domestic Taiwanese operations, diluting TSMC''s corporate gross margins.\nRelated DIP Lesson: Lesson - Corporate actions: Lesson 5 (Massive CapEx: The Downside Risk: Killing Short-Term Margins & Execution Risk): Overseas fab expansions face high cost inflation and execution hurdles, requiring unexpected capital injections that burn cash and depress near-term profit margins.',
 1),

(114, 'corporate', 'real_news', 109,
 'Headline: ''Samsung borrows $16 billion from display subsidiary to fund chip investment''\nConsidering this is a Corporate actions event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Surges +5.5%: Borrowing $16B from Samsung Display provided massive cheap internal liquidity without issuing dilutive corporate bonds.', 'Drops -1.58%: Borrowing $16B from a subsidiary highlighted severe cash flow strain in the semiconductor division caused by the cyclical memory crash.', 'Crashes -10.0%: The internal loan triggered an immediate debt default across Samsung Electronics'' overseas credit facilities.',
 'b',
 'The stock dropped 1.58% the following day (lagging the sector''s +0.40% rise).\nExplanation & Article Drivers: Samsung Electronics borrowed 20 trillion won ($16B) from its display affiliate Samsung Display to fund its semiconductor CapEx during the memory downturn. The stock declined because the unusual internal loan highlighted the intense liquidity strain and cash burn caused by Samsung''s refusal to cut CapEx, raising investor concerns over balance-sheet leverage.\nRelated DIP Lesson: Lesson - Corporate actions: Lesson 5 (Massive CapEx: The Oversupply Trap and Cash Drain): Maintaining aggressive CapEx through debt or inter-company borrowing during an industry downturn strains corporate liquidity and elevates financial risk.',
 1),

(115, 'corporate', 'real_news', 110,
 'Headline: ''Micron expands stock buyback program as memory market recovers''\nConsidering this is a Corporate actions event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Surges +9.0%: Resuming share repurchases convinced Wall Street that Micron''s quarterly profitability had permanently reached record levels.', 'Remains unchanged (0.00%): The announcement was a routine corporate filing with no influence on institutional trading desks.', 'Drops -2.16%: Expanding buybacks failed to overcome broad memory sector weakness and investor concerns over heavy HBM capital expenditure requirements.',
 'c',
 'The stock dropped 2.16% the following day (in line with the sector''s -1.12% decline).\nExplanation & Article Drivers: Micron expanded its share repurchase authorization as memory market spot prices began to recover. While buybacks typically support share prices, Micron fell alongside a broader market dip as investors took profits following a prior rally and questioned deploying cash into buybacks before operating cash flows had turned definitively positive.\nRelated DIP Lesson: Lesson - Corporate actions: Lesson 2 / 3 (Capital Allocation: Stock Buybacks vs Cash Conservation): Resuming share repurchases signals confidence, but investors may react cautiously if buybacks precede a full cash-flow recovery during cyclical inflections.',
 0),

(116, 'corporate', 'real_news', 111,
 'Headline: ''Intel agrees to sell 20% stake in IMS Nanofabrication to Bain Capital''\nConsidering this is a Corporate actions event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Slips -0.58%: Selling a 20% stake in IMS Nanofabrication to Bain Capital raised $860M in cash, but investors focused on broader foundry execution challenges.', 'Surges +8.0%: Valuing IMS at $4.3B proved that Intel''s internal equipment subsidiaries were worth more than the entire core company.', 'Plunges -7.0%: Selling a minority stake in multi-beam mask tools was viewed as surrendering critical lithography intellectual property.',
 'a',
 'The stock slipped 0.58% the following day (lagging the sector''s +0.46% gain).\nExplanation & Article Drivers: Intel agreed to sell a 20% stake in its multi-beam mask-writing subsidiary IMS Nanofabrication to Bain Capital at a $4.3 billion valuation. While the transaction raised non-debt cash and validated IMS''s technology value, the stock stayed subdued because investors remained focused on Intel''s larger core manufacturing losses and heavy multi-year fab investments.\nRelated DIP Lesson: Lesson - Corporate actions: Lesson 1 (Strategic Restructuring and Spinoffs: Partial Asset Sales): Selling minority stakes in specialized technology subsidiaries validates asset valuation and raises non-debt capital, though overall stock reaction depends on core turnaround execution.',
 0),

(117, 'supply_chain', 'real_news', 112,
 'Headline: ''Taiwan earthquake halts TSMC production, highlights supply chain risks''\nConsidering this is a Supply chain event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Falls -1.65%: While thousands of in-process wafers were scrapped from tool shutdowns, restoring 70%+ of fab tooling within 10 hours helped TSMC outperform a -2.83% sector drop.', 'Crashes -15.0%: A 7.4-magnitude earthquake permanently leveled TSMC''s Taichung and Tainan gigafabs, halting global chip supply for months.', 'Surges +6.0%: Wafer loss fears allowed TSMC to immediately triple wafer contract prices across all global fabless clients.',
 'a',
 'The stock price fell 1.65% the following day (outperforming the sector''s -2.83% drop).\nExplanation & Article Drivers: A powerful 7.4-magnitude earthquake struck Taiwan, triggering automatic emergency shutdowns across TSMC''s advanced fabrication cleanrooms. While automated safety systems prevented catastrophic structural damage, quartz wafer tubes broke and thousands of in-process wafers were scrapped. The stock declined on immediate yield loss and downtime costs, but outperformed the broader sector because TSMC restored over 70% of tooling within 10 hours, demonstrating unmatched operational resilience.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks: Production Disruptions) & Lesson 1 (Foundries): Highlights how geographical natural disasters create sudden supply-chain bottlenecks for foundries operating high-utilization advanced nodes, though superior disaster recovery limits financial fallout.',
 1),

(118, 'supply_chain', 'real_news', 113,
 'Headline: ''Intel delays $20B Ohio fab timeline to 2026 citing market conditions''\nConsidering this is a Supply chain event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Surges +7.0%: Delaying Ohio fab spending was cheered by Wall Street as an immediate multi-billion-dollar boost to free cash flow.', 'Falls -1.75%: Pushing Ohio fab completion from 2025 to 2026 underscored slowing PC/server chip demand and raised doubts about IFS foundry competitiveness.', 'Plummets -12.0%: Delaying construction prompted the US Commerce Department to revoke all federal CHIPS Act subsidies for Intel.',
 'b',
 'The stock price fell 1.75% the following day (lagging the sector''s +1.27% gain).\nExplanation & Article Drivers: Intel announced it was pushing back the construction completion and production timeline of its $20B Columbus, Ohio mega-fab from 2025 to late 2026, citing persistent consumer PC market weakness and slow disbursement of US CHIPS Act grants. Investors penalized the stock because delaying fab completion postponed Intel''s ability to generate foundry revenue from external clients and raised skepticism over its IDM 2.0 execution pacing.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 3 (Semiconductor Cycles: Overinvestment & Downturn Phase) & Lesson 4 (CapEx Management): Demonstrates how cyclical downturns and weak end-market demand force manufacturers to throttle capital expenditure and push back fab rollout schedules.',
 1),

(119, 'supply_chain', 'real_news', 114,
 'Headline: ''TSMC delays Arizona fab production to 2025 due to skilled worker shortage''\nConsidering this is a Supply chain event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rallies +4.5%: Delaying Arizona production allowed TSMC to redirect capital back to its higher-margin Taiwanese gigafabs.', 'Plunges -8.0%: A one-year production delay led Apple to cancel all future US-manufactured 4nm chip orders.', 'Slips -0.62%: Delaying 4nm production to 2025 due to US skilled labor shortages highlighted friction in overseas expansion, though long-term demand cushioned the stock.',
 'c',
 'The stock price slipped 0.62% the following day (trailing the sector''s +0.90% rise).\nExplanation & Article Drivers: TSMC delayed the start of 4nm mass production at its Phoenix, Arizona fab from 2024 to 2025, citing a severe shortage of specialized local technicians required to install advanced cleanroom equipment. The stock slipped mildly because the delay confirmed that replicating Taiwan''s efficient fabrication ecosystem in the US involved higher operational friction and execution delays, pushing back revenue generation from US fab capacity.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks: Production Disruptions & Lead Times) & Lesson 1 (Foundry Operations): Illustrates how skilled labor shortages in overseas supply chains create installation bottlenecks that delay fab commercialization.',
 1),

(120, 'supply_chain', 'real_news', 115,
 'Headline: ''TSMC delays second Arizona fab to 2027 or 2028''\nConsidering this is a Supply chain event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Rises +1.04%: Pushing the second Arizona fab to 2027/2028 paced capital expenditure prudently against market demand, supporting the stock during a broad tech rally.', 'Crashes -10.0%: Pushing back fab completion signaled TSMC was completely abandoning its US manufacturing roadmap.', 'Surges +14.0%: Pushing back fab timelines prompted the US government to double direct grant subsidies for the Arizona complex.',
 'a',
 'The stock price rose 1.04% the following day (sector +3.91%).\nExplanation & Article Drivers: TSMC pushed back the production timeline for its second Arizona fab from 2026 to 2027 or 2028, citing ongoing US subsidy negotiations and macro demand uncertainty. While delaying capacity buildouts is often negative, the stock advanced alongside a surging market because postponing heavy CapEx reduced near-term cash burn and protected corporate gross margins while negotiations with the US government progressed.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 4 (Financial Metrics: CapEx & Free Cash Flow) & Lesson 3 (Semiconductor Cycles): Delaying capital-intensive fab phases during uncertain demand protects near-term free cash flow and shields gross margins from premature fixed depreciation expenses.',
 0),

(121, 'supply_chain', 'real_news', 116,
 'Headline: ''ASML ships industry''s first High-NA EUV lithography system to Intel''\nConsidering this is a Supply chain event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Surges +8.0%: Shipping the industry''s first High-NA system gave ASML an instant multi-billion-euro revenue recognition boost.', 'Dips -0.36%: Shipping the initial R&D pilot tool was widely anticipated and priced in, keeping price action muted during an overall quiet sector day.', 'Plunges -6.0%: High-NA tool shipment costs were reported to be so high that ASML took an immediate gross margin loss on the unit.',
 'b',
 'The stock price dipped 0.36% the following day (lagging the sector''s +0.32% gain).\nExplanation & Article Drivers: ASML shipped the industry''s first commercial High-NA EUV lithography system (Twinscan EXE:5000) to Intel''s Hillsboro, Oregon facility. Despite achieving an extraordinary technological milestone, ASML''s stock dipped slightly as investors recognized that High-NA tools are multi-year R&D projects with extensive assembly and calibration lead times, meaning meaningful commercial wafer production and recurring tool revenue would not materialize until 2025-2026.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Semiconductor Industry Structure: Equipment) & Lesson 2 (Lead Times & CapEx Deployment): Equipment tool shipments involve multi-year lead times and complex customer tool calibration before translating into high-volume commercial chip output.',
 0),

(122, 'supply_chain', 'real_news', 117,
 'Headline: ''Samsung makes meaningful cut to memory chip production''\nConsidering this is a Supply chain event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -4.5%: Slashing memory production confirmed that Samsung was losing money on every DRAM and NAND wafer produced.', 'Surges +10.0%: Meaningful production cuts immediately caused global spot memory prices to double overnight.', 'Gains +1.08%: Samsung joining industry-wide production cuts signaled an accelerated bottoming of memory oversupply, lifting sentiment across cyclical tech.',
 'c',
 'The stock price gained 1.08% the following day (defying a sector decline of -0.52%).\nExplanation & Article Drivers: Samsung made the historic announcement that it was cutting memory chip production by a ''meaningful level,'' reversing its longstanding refusal to cut output during down-cycles. The stock rallied because Samsung controls over 40% of global DRAM supply; its capitulation signaled the definitive end of the memory glut, setting the stage for inventory normalization and future price increases.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 3 (Semiconductor Cycles: Stage 5 Oversupply to Recovery) & Lesson 4 (Memory ASP Dynamics): Shows how supplier production cuts in commodity-like memory markets resolve industry oversupply, allowing average selling prices (ASPs) and margins to recover.',
 1),

(123, 'supply_chain', 'real_news', 118,
 'Headline: ''Micron says Taiwan earthquake will impact a single digit percentage of quarterly supply''\nConsidering this is a Supply chain event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -3.91%: Revealing that the Taiwan earthquake would hit a single-digit percentage of quarterly supply heightened near-term revenue friction, tracking a sector selloff.', 'Surges +5.0%: Supply constraints enabled Micron to raise quarterly contract pricing by 25% across all major PC OEM customers.', 'Plummets -14.0%: The earthquake caused catastrophic physical damage to Micron''s Taichung fab cleanrooms, halting output indefinitely.',
 'a',
 'The stock price dropped 3.91% the following day (underperforming the sector''s -3.28% drop).\nExplanation & Article Drivers: Micron disclosed that the Taiwan earthquake would reduce its calendar Q2 DRAM supply by up to a high-single-digit percentage, as its Taoyuan and Taichung facilities experienced temporary cleanroom shutdowns and wafer scrap. The stock fell sharply as investors feared immediate revenue losses and delivery disruptions, though tight supply subsequently accelerated global memory contract price increases.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply Chains and Semiconductor Stocks: Production Disruptions) & Lesson 4 (Bit Shipments vs ASP): Unplanned natural disasters temporarily slash bit shipments, but the resulting supply scarcity enhances pricing power across remaining inventory.',
 1),

(124, 'supply_chain', 'real_news', 119,
 'Headline: ''Nvidia warns CoWoS advanced packaging is the primary bottleneck for AI chips''\nConsidering this is a Supply chain event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Crashes -10.0%: Warning of CoWoS packaging bottlenecks sparked fears that Nvidia''s AI accelerator shipments would collapse in the coming quarter.', 'Finishes flat (+0.08%): Warning that advanced packaging was the primary bottleneck confirmed that customer demand vastly exceeded supply, holding shares steady.', 'Surges +12.0%: Packaging bottlenecks forced cloud hyperscalers to prepay 100% upfront for future GPU deliveries.',
 'b',
 'The stock price finished flat at +0.08% the following day (outperforming the sector''s -3.30% slump).\nExplanation & Article Drivers: Nvidia disclosed that insatiable demand for its H100 AI processors was severely constrained by TSMC''s Chip-on-Wafer-on-Substrate (CoWoS) advanced packaging capacity. While packaging shortages prevented Nvidia from meeting massive customer backlogs, the stock held positive ground because the bottleneck demonstrated astronomical structural demand, ensuring pricing power and maximum gross margins.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Semiconductor Industry Structure: Packaging and Testing) & Lesson 2 (Supply-Chain Tightness: Lead Times & Demand): Highlights how advanced packaging serves as the primary choke-point for AI accelerators, creating severe lead times despite ample front-end wafer fabrication.',
 1),

(125, 'supply_chain', 'real_news', 120,
 'Headline: ''ASML orders drop sharply as TSMC and Intel push out equipment deliveries''\nConsidering this is a Supply chain event, how do you expect this news to influence ASML''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Plummets -9.0%: Order push-outs from major foundry clients confirmed that the semiconductor manufacturing equipment supercycle was collapsing.', 'Surges +6.0%: ASML announced full financial penalties collected from TSMC and Intel for delaying equipment deliveries.', 'Rises +0.77%: While orders softened, ASML''s massive multi-year lithography backlog and resilient EUV demand helped the stock outperform a broader sector drop.',
 'c',
 'The stock price rose 0.77% the following day (outperforming the sector''s -1.54% drop).\nExplanation & Article Drivers: ASML reported a sequential drop in net bookings as foundries delayed equipment delivery schedules to align with sluggish consumer electronics demand. ASML stock held up because management reaffirmed that 2024 was a well-telegraphed ''transition year,'' and emphasized that customer fab pushouts represented delayed deliveries rather than order cancellations, backed by a €35B+ backlog.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 2 (Supply-Chain Indicators: CapEx & Backlog) & Lesson 1 (Equipment Sensitivity to Foundry Cycles): Foundry customers push out equipment deliveries when capacity utilization drops, but deep tool backlogs insulate equipment makers from outright cancellations.',
 0),

(126, 'supply_chain', 'real_news', 121,
 'Headline: ''Intel secures entire 2024 supply of ASML''s High-NA EUV machines''\nConsidering this is a Supply chain event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -2.36%: Locking up ASML''s entire 2024 High-NA output sparked investor anxiety over heavy CapEx cash burn and high integration execution risk.', 'Surges +8.0%: Securing all High-NA tools guaranteed Intel would immediately regain global process leadership over TSMC at 18A.', 'Plunges -12.0%: ASML cancelled the allocation agreement due to Intel''s deteriorating corporate credit rating.',
 'a',
 'The stock price dropped 2.36% the following day (underperforming the sector''s -0.23% dip).\nExplanation & Article Drivers: Intel moved aggressively to lock up ASML''s entire 2024 production run of six High-NA EUV machines (~$350M each) to gain an edge for its upcoming 18A and 14A nodes. Despite boxing out rivals TSMC and Samsung, Intel shares slid because investors were alarmed by the massive capital expenditure outlay ($2B+) and high technical integration risks before commercial foundry customers had signed contracts.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 4 (Capital Expenditure & Free Cash Flow) & Lesson 1 (Equipment & Process Node Leadership): Front-loading equipment CapEx locks in leading-edge technology, but burning billions without guaranteed commercial volume strains return on invested capital.',
 0),

(127, 'supply_chain', 'real_news', 122,
 'Headline: ''Micron begins mass production of HBM3E memory for Nvidia''s H200 AI chips''\nConsidering this is a Supply chain event, how do you expect this news to influence Micron''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -3.0%: Entering mass production was overshadowed by Wall Street skepticism regarding Micron''s HBM packaging yields.', 'Rises +2.67%: Mass-producing 24GB 8-High HBM3E for Nvidia H200 GPUs proved technological parity with SK Hynix, driving multiple expansion.', 'Surges +18.0%: Mass production guaranteed Micron 100% exclusive market share for all high-bandwidth memory used in Blackwell AI superchips.',
 'b',
 'The stock price rose 2.67% the following day (outperforming the flat sector at -0.10%).\nExplanation & Article Drivers: Micron announced volume production of its 24GB 8-High HBM3E memory module, which was selected to power Nvidia''s next-generation H200 Tensor Core GPUs, offering 30% lower power consumption than rivals. The stock jumped as investors cheered this premier design win, proving Micron had leapfrogged competitor Samsung to become a primary high-bandwidth memory supplier to Nvidia.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Memory Manufacturers: HBM Design Wins) & Lesson 2 (Supply Chains and Semiconductor Stocks: Rising End-Market Demand): Securing tier-1 qualification for AI accelerators provides massive volume visibility and drives structural gross margin expansion.',
 1),

(128, 'supply_chain', 'real_news', 123,
 'Headline: ''SK Hynix says HBM chips sold out for 2024, ramping pressure on Samsung''\nConsidering this is a Supply chain event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Surges +6.5%: Rival SK Hynix selling out of HBM capacity meant all remaining unfulfilled cloud AI memory orders would default to Samsung.', 'Crashes -9.0%: Investors dumped Samsung shares on rumors that its memory division would be completely shut out of the AI market.', 'Falls -0.51%: SK Hynix selling out of 2024 HBM capacity highlighted Samsung''s ongoing struggle to pass Nvidia qualification for its competing HBM3E chips.',
 'c',
 'The stock price fell 0.51% the following day (lagging the sector''s +2.25% rally).\nExplanation & Article Drivers: SK Hynix announced its entire 2024 and 2025 HBM production capacity was completely sold out. Samsung fell while the sector rallied because SK Hynix''s sold-out status underscored Samsung''s delayed qualification for Nvidia''s HBM3E chips, highlighting that Samsung was losing lucrative AI memory market share to its arch-rival.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Memory Manufacturers & Advanced Packaging) & Lesson 2 (Customer Orders & Market Share Shifts): When memory capacity in an AI boom is fully booked by a rival, lagging competitors suffer valuation discounts due to missed high-margin product cycles.',
 1),

(129, 'supply_chain', 'real_news', 124,
 'Headline: ''TSMC to invest nearly $3 billion for new advanced packaging plant in Taiwan''\nConsidering this is a Supply chain event, how do you expect this news to influence TSMC''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -0.91%: Investing $2.9B in a new advanced packaging fab addressed chronic CoWoS bottlenecks, though heavy CapEx kept gains muted during a sector dip.', 'Surges +7.0%: The new packaging fab immediately quadrupled TSMC''s monthly advanced packaging capacity within weeks.', 'Plunges -6.0%: Investors penalized TSMC for concentrating additional manufacturing CapEx in geopolitically vulnerable Miaoli, Taiwan.',
 'a',
 'The stock price dropped 0.91% the following day (outperforming the sector''s -1.38% drop).\nExplanation & Article Drivers: TSMC announced an investment of nearly NT$90B ($2.9B) to construct a dedicated advanced packaging fab in Tongluo, Taiwan, to double its CoWoS capacity and alleviate the worldwide AI hardware bottleneck. The stock experienced mild pressure alongside a weak sector, as investors weighed the substantial CapEx commitment against the 2027 operational timeline.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Packaging and Testing as Industry Bottleneck) & Lesson 2 (Capacity Expansion): Heavy capital deployment into advanced packaging addresses critical supply bottlenecks, but multi-year construction leads to short-term cash flow outlays before revenues ramp.',
 1),

(130, 'supply_chain', 'real_news', 125,
 'Headline: ''Samsung shifts legacy semiconductor capacity to focus on HBM''\nConsidering this is a Supply chain event, how do you expect this news to influence Samsung''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Plummets -8.0%: Cannibalizing legacy DRAM lines triggered severe revenue shortfalls across consumer electronics segments.', 'Rises +2.54%: Reallocating legacy capacity to high-margin HBM production was applauded as a proactive shift to capture surging enterprise AI memory demand.', 'Surges +12.0%: The capacity conversion immediately made Samsung the largest global supplier of HBM chips by volume.',
 'b',
 'The stock price rose 2.54% the following day (outperforming the sector''s +2.35% gain).\nExplanation & Article Drivers: Samsung announced it was reallocating legacy DRAM production lines to high-bandwidth memory (HBM) and DDR5. The stock climbed because repurposing existing wafer fab capacity accelerated Samsung''s AI memory catch-up while simultaneously cutting legacy DDR4 supply, creating a double positive: tightening general DRAM supply and boosting exposure to high-margin HBM.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 3 (Semiconductor Cycles: Capacity Reallocation) & Lesson 4 (Product Mix & Gross Margin): Shifting wafer fabrication from low-margin legacy products to high-ASP specialty chips optimizes factory utilization and accelerates gross margin expansion.',
 0),

(131, 'supply_chain', 'real_news', 126,
 'Headline: ''Intel announces massive advanced packaging facility expansion in Malaysia''\nConsidering this is a Supply chain event, how do you expect this news to influence Intel''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Drops -4.0%: Adding packaging capacity in Malaysia raised concerns over elevated logistics costs between US wafer fabs and Asian packaging lines.', 'Surges +15.0%: Expanding in Penang fully solved all global advanced packaging constraints for Intel''s client and server processors.', 'Rises +3.31%: Expanding Malaysian advanced packaging infrastructure reinforced Intel''s IFS strategy to provide turnkey packaging services for external customers.',
 'c',
 'The stock price rose 3.31% the following day (outperforming the sector''s +2.04% gain).\nExplanation & Article Drivers: Intel announced a $7 billion expansion of its advanced chip packaging operations in Penang, Malaysia, showcasing its proprietary Foveros 3D packaging technology. Investors welcomed the news because advanced packaging was a massive global supply-chain bottleneck; expanding independent capacity gave Intel a viable opening to attract external foundry customers seeking alternatives to TSMC.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Semiconductor Industry Structure: Advanced Packaging) & Lesson 2 (Supply-Chain Strength): Building world-class advanced packaging capacity breaks rival foundries'' backend monopolies, providing a crucial competitive advantage in winning AI foundry contracts.',
 0),

(132, 'supply_chain', 'real_news', 127,
 'Headline: ''Nvidia unveils Blackwell architecture, securing massive TSMC 4NP capacity''\nConsidering this is a Supply chain event, how do you expect this news to influence NVDA''s stock price? What specific factors, risks, or investor expectations might drive the price up or down?',
 'Gains +1.06%: Unveiling Blackwell and locking in TSMC 4NP wafer and CoWoS-L packaging capacity cemented Nvidia''s generative AI hardware dominance.', 'Drops -5.0%: Unveiling a dual-die chip design sparked panic over extreme manufacturing complexity and potential thermal throttling.', 'Surges +12.0%: Blackwell''s announcement prompted cloud hyperscalers to cancel all existing orders for rival AMD Instinct accelerators.',
 'a',
 'The stock price gained 1.06% the following day (defying a sector decline of -0.84%).\nExplanation & Article Drivers: At GTC 2024, Nvidia unveiled its next-generation Blackwell B200 GPU, featuring 208 billion transistors manufactured on TSMC''s custom 4NP process. The stock rose against a falling market because Nvidia locked up massive TSMC wafer allocations and advanced packaging lines, ensuring supply dominance and rendering it nearly impossible for rival chip designers to secure sufficient fab capacity.\nRelated DIP Lesson: Lesson - Supply-chain: Lesson 1 (Fabless Chip Designers: Capacity Allocation) & Lesson 2 (Customer Orders & End-Market Demand): Market-leading fabless designers use massive balance-sheet power to pre-book foundry and packaging capacity, locking out competitors and driving revenue expansion.',
 1),

